/**
 * Core type definitions for family tree data structures
 */

/**
 * Gender options for a person
 */
export type Gender = "male" | "female" | "other" | "unknown";

/**
 * Structured name with optional components
 */
export interface PersonName {
  first: string;
  middle?: string;
  last?: string;
  maiden?: string;
  suffix?: string;
  prefix?: string;
  nickname?: string;
}

/**
 * Date with optional precision indicator.
 * For birthdays/anniversaries, only date is stored (no time).
 */
export interface DateInfo {
  /**
   * ISO 8601 date string.
   * For birthdays/deathdays/anniversaries: YYYY-MM-DD format (date only)
   * For other timestamps: Full ISO 8601 with time
   */
  date: string;
  approximate?: boolean;
  notes?: string;
}

/**
 * Location information
 */
export interface Location {
  city?: string;
  state?: string;
  country?: string;
  address?: string;
  notes?: string;
}

/**
 * Life event types
 */
export type EventType =
  | "birth"
  | "death"
  | "marriage"
  | "divorce"
  | "graduation"
  | "immigration"
  | "emigration"
  | "retirement"
  | "custom";

/**
 * A life event for a person
 */
export interface LifeEvent {
  type: EventType;
  date?: DateInfo;
  location?: Location;
  description?: string;
  notes?: string;
}

/**
 * Contact information
 */
export interface ContactInfo {
  email?: string;
  phone?: string;
  address?: Location;
}

/**
 * A person in the family tree
 */
export interface PersonData {
  id: string;
  name: PersonName;
  gender: Gender;
  birth?: DateInfo;
  death?: DateInfo;
  birthPlace?: Location;
  deathPlace?: Location;
  events?: LifeEvent[];
  contact?: ContactInfo;
  notes?: string;
  occupation?: string;
  education?: string;
  createdAt: string;
  updatedAt: string;
  // Relationship IDs
  fatherId?: string;
  motherId?: string;
  spouseIds?: string[];
  childIds?: string[];
}

/**
 * Types of family relationships
 */
export type RelationshipType =
  | "spouse"
  | "parent-child"
  | "adopted"
  | "step-parent"
  | "step-child"
  | "guardian";

/**
 * Status of a relationship
 */
export type RelationshipStatus = "active" | "divorced" | "separated" | "widowed" | "ended";

/**
 * A relationship between two people
 */
export interface Relationship {
  id: string;
  type: RelationshipType;
  person1Id: string;
  person2Id: string;
  status: RelationshipStatus;
  startDate?: DateInfo;
  endDate?: DateInfo;
  notes?: string;
}

/**
 * Family tree metadata
 */
export interface TreeMetadata {
  name: string;
  description?: string;
  created: string;
  modified: string;
  version: string;
}

/**
 * Complete family tree data structure
 */
export interface FamilyTreeData {
  meta: TreeMetadata;
  people: Record<string, PersonData>;
  relationships: Relationship[];
}

/**
 * Input for creating a new person (without generated fields)
 */
export interface CreatePersonInput {
  name: PersonName;
  gender?: Gender;
  birth?: DateInfo;
  death?: DateInfo;
  birthPlace?: Location;
  deathPlace?: Location;
  events?: LifeEvent[];
  contact?: ContactInfo;
  notes?: string;
  occupation?: string;
  education?: string;
  fatherId?: string;
  motherId?: string;
  spouseIds?: string[];
}

/**
 * Input for updating a person
 */
export type UpdatePersonInput = Partial<Omit<PersonData, "id" | "createdAt">>;
