/**
 * Main FamilyTree class for managing family data
 */

import type {
  CreatePersonInput,
  FamilyTreeData,
  PersonData,
  Relationship,
  TreeMetadata,
  UpdatePersonInput,
} from "../types/family.js";
import { FamilyTreeError } from "../types/errors.js";
import { generateId } from "./id-generator.js";
import { createPerson, updatePerson } from "./person.js";
import {
  addRelationship,
  removeRelationship,
  findRelationshipsBetween,
  type AddRelationshipInput,
} from "./relationships.js";
import { validatePerson, validateRelationship, validateFamilyTree } from "./validation.js";

const CURRENT_VERSION = "1.0.0";

/**
 * Creates a new empty family tree
 */
export function createFamilyTree(name: string, description?: string): FamilyTreeData {
  const now = new Date().toISOString();

  return {
    meta: {
      name,
      description,
      created: now,
      modified: now,
      version: CURRENT_VERSION,
    },
    people: {},
    relationships: [],
  };
}

/**
 * Updates tree metadata modification timestamp
 */
function touchTree(tree: FamilyTreeData): FamilyTreeData {
  return {
    ...tree,
    meta: {
      ...tree.meta,
      modified: new Date().toISOString(),
    },
  };
}

/**
 * Adds a person to the family tree
 */
export function addPerson(tree: FamilyTreeData, input: CreatePersonInput): FamilyTreeData {
  const id = generateId();
  const person = createPerson(id, input);

  // Validate the person
  const errors = validatePerson(person, tree);
  if (errors.length > 0) {
    throw new FamilyTreeError(`Invalid person data: ${errors.map((e) => e.message).join(", ")}`);
  }

  let updatedTree: FamilyTreeData = {
    ...tree,
    people: {
      ...tree.people,
      [id]: person,
    },
  };

  // Add parent-child relationships if parents specified
  if (input.fatherId) {
    if (!tree.people[input.fatherId]) {
      throw new FamilyTreeError(`Father with ID ${input.fatherId} not found`);
    }
    updatedTree = addRelationship(updatedTree, {
      type: "parent-child",
      person1Id: input.fatherId,
      person2Id: id,
    });

    // Update father's childIds
    const father = updatedTree.people[input.fatherId];
    if (father) {
      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [input.fatherId]: {
            ...father,
            childIds: [...(father.childIds || []), id],
          },
        },
      };
    }
  }

  if (input.motherId) {
    if (!tree.people[input.motherId]) {
      throw new FamilyTreeError(`Mother with ID ${input.motherId} not found`);
    }
    updatedTree = addRelationship(updatedTree, {
      type: "parent-child",
      person1Id: input.motherId,
      person2Id: id,
    });

    // Update mother's childIds
    const mother = updatedTree.people[input.motherId];
    if (mother) {
      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [input.motherId]: {
            ...mother,
            childIds: [...(mother.childIds || []), id],
          },
        },
      };
    }
  }

  // Add spouse relationships if specified
  if (input.spouseIds) {
    for (const spouseId of input.spouseIds) {
      if (!tree.people[spouseId]) {
        throw new FamilyTreeError(`Spouse with ID ${spouseId} not found`);
      }
      updatedTree = addRelationship(updatedTree, {
        type: "spouse",
        person1Id: id,
        person2Id: spouseId,
      });

      // Update spouse's spouseIds
      const spouse = updatedTree.people[spouseId];
      if (spouse) {
        updatedTree = {
          ...updatedTree,
          people: {
            ...updatedTree.people,
            [spouseId]: {
              ...spouse,
              spouseIds: [...(spouse.spouseIds || []), id],
            },
          },
        };
      }
    }
  }

  return touchTree(updatedTree);
}

/**
 * Updates a person in the family tree
 */
export function editPerson(
  tree: FamilyTreeData,
  personId: string,
  updates: UpdatePersonInput
): FamilyTreeData {
  const person = tree.people[personId];
  if (!person) {
    throw new FamilyTreeError(`Person with ID ${personId} not found`);
  }

  const updatedPerson = updatePerson(person, updates);

  // Validate the updated person
  const tempTree = {
    ...tree,
    people: {
      ...tree.people,
      [personId]: updatedPerson,
    },
  };

  const errors = validatePerson(updatedPerson, tempTree);
  if (errors.length > 0) {
    throw new FamilyTreeError(`Invalid person data: ${errors.map((e) => e.message).join(", ")}`);
  }

  return touchTree(tempTree);
}

/**
 * Removes a person from the family tree
 */
export function removePerson(
  tree: FamilyTreeData,
  personId: string,
  options: { cascade?: boolean } = {}
): FamilyTreeData {
  const person = tree.people[personId];
  if (!person) {
    throw new FamilyTreeError(`Person with ID ${personId} not found`);
  }

  // Check for relationships
  const relatedRelationships = tree.relationships.filter(
    (r) => r.person1Id === personId || r.person2Id === personId
  );

  if (relatedRelationships.length > 0 && !options.cascade) {
    throw new FamilyTreeError(
      `Cannot delete person with existing relationships. Use cascade option to remove relationships.`
    );
  }

  // Remove the person
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const { [personId]: _, ...remainingPeople } = tree.people;

  // Remove related relationships
  const remainingRelationships = tree.relationships.filter(
    (r) => r.person1Id !== personId && r.person2Id !== personId
  );

  // Update references in other people
  const updatedPeople = Object.fromEntries(
    Object.entries(remainingPeople).map(([id, p]) => {
      const updates: Partial<PersonData> = {};

      if (p.fatherId === personId) updates.fatherId = undefined;
      if (p.motherId === personId) updates.motherId = undefined;
      if (p.spouseIds?.includes(personId)) {
        updates.spouseIds = p.spouseIds.filter((sid) => sid !== personId);
      }
      if (p.childIds?.includes(personId)) {
        updates.childIds = p.childIds.filter((cid) => cid !== personId);
      }

      if (Object.keys(updates).length > 0) {
        return [id, { ...p, ...updates }];
      }
      return [id, p];
    })
  );

  return touchTree({
    ...tree,
    people: updatedPeople,
    relationships: remainingRelationships,
  });
}

/**
 * Gets a person by ID
 */
export function getPerson(tree: FamilyTreeData, personId: string): PersonData | undefined {
  return tree.people[personId];
}

/**
 * Gets all people in the tree
 */
export function getAllPeople(tree: FamilyTreeData): PersonData[] {
  return Object.values(tree.people);
}

/**
 * Adds a relationship to the tree
 */
export function addTreeRelationship(
  tree: FamilyTreeData,
  input: AddRelationshipInput
): FamilyTreeData {
  // Validate people exist
  if (!tree.people[input.person1Id]) {
    throw new FamilyTreeError(`Person with ID ${input.person1Id} not found`);
  }
  if (!tree.people[input.person2Id]) {
    throw new FamilyTreeError(`Person with ID ${input.person2Id} not found`);
  }

  // Check for existing relationship
  const existing = findRelationshipsBetween(tree, input.person1Id, input.person2Id);
  if (existing.some((r) => r.type === input.type)) {
    throw new FamilyTreeError(
      `A ${input.type} relationship already exists between these people`
    );
  }

  const updatedTree = addRelationship(tree, input);

  // Validate the new relationship
  const newRelationship = updatedTree.relationships.at(-1);
  if (newRelationship) {
    const errors = validateRelationship(newRelationship, updatedTree);
    if (errors.length > 0) {
      throw new FamilyTreeError(
        `Invalid relationship: ${errors.map((e) => e.message).join(", ")}`
      );
    }
  }

  // Update person references based on relationship type
  let finalTree = updatedTree;

  if (input.type === "spouse") {
    const person1 = finalTree.people[input.person1Id];
    const person2 = finalTree.people[input.person2Id];

    if (person1 && person2) {
      finalTree = {
        ...finalTree,
        people: {
          ...finalTree.people,
          [input.person1Id]: {
            ...person1,
            spouseIds: [...(person1.spouseIds || []), input.person2Id],
          },
          [input.person2Id]: {
            ...person2,
            spouseIds: [...(person2.spouseIds || []), input.person1Id],
          },
        },
      };
    }
  } else if (input.type === "parent-child") {
    const parent = finalTree.people[input.person1Id];
    const child = finalTree.people[input.person2Id];

    if (parent && child) {
      const parentUpdate: Partial<PersonData> = {
        childIds: [...(parent.childIds || []), input.person2Id],
      };

      const childUpdate: Partial<PersonData> =
        parent.gender === "male"
          ? { fatherId: input.person1Id }
          : parent.gender === "female"
            ? { motherId: input.person1Id }
            : {};

      finalTree = {
        ...finalTree,
        people: {
          ...finalTree.people,
          [input.person1Id]: { ...parent, ...parentUpdate },
          [input.person2Id]: { ...child, ...childUpdate },
        },
      };
    }
  }

  return touchTree(finalTree);
}

/**
 * Removes a relationship from the tree
 */
export function removeTreeRelationship(
  tree: FamilyTreeData,
  relationshipId: string
): FamilyTreeData {
  const relationship = tree.relationships.find((r) => r.id === relationshipId);
  if (!relationship) {
    throw new FamilyTreeError(`Relationship with ID ${relationshipId} not found`);
  }

  let updatedTree = removeRelationship(tree, relationshipId);

  // Update person references
  if (relationship.type === "spouse") {
    const person1 = updatedTree.people[relationship.person1Id];
    const person2 = updatedTree.people[relationship.person2Id];

    if (person1) {
      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [relationship.person1Id]: {
            ...person1,
            spouseIds: person1.spouseIds?.filter((id) => id !== relationship.person2Id),
          },
        },
      };
    }

    if (person2) {
      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [relationship.person2Id]: {
            ...person2,
            spouseIds: person2.spouseIds?.filter((id) => id !== relationship.person1Id),
          },
        },
      };
    }
  } else if (relationship.type === "parent-child") {
    const parent = updatedTree.people[relationship.person1Id];
    const child = updatedTree.people[relationship.person2Id];

    if (parent) {
      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [relationship.person1Id]: {
            ...parent,
            childIds: parent.childIds?.filter((id) => id !== relationship.person2Id),
          },
        },
      };
    }

    if (child) {
      const childUpdate: Partial<PersonData> = {};
      if (child.fatherId === relationship.person1Id) childUpdate.fatherId = undefined;
      if (child.motherId === relationship.person1Id) childUpdate.motherId = undefined;

      updatedTree = {
        ...updatedTree,
        people: {
          ...updatedTree.people,
          [relationship.person2Id]: {
            ...child,
            ...childUpdate,
          },
        },
      };
    }
  }

  return touchTree(updatedTree);
}

