/**
 * Gets tree statistics
 */
export function getStats(tree: FamilyTreeData): {
  totalPeople: number;
  totalRelationships: number;
  generations: number;
  oldestPerson: PersonData | null;
  youngestPerson: PersonData | null;
} {
  const people = getAllPeople(tree);

  // Calculate generations (simplified - counts max depth from roots)
  const roots = people.filter((p) => !p.fatherId && !p.motherId);

  function getDepth(personId: string, visited = new Set<string>()): number {
    if (visited.has(personId)) return 0;
    visited.add(personId);

    const person = tree.people[personId];
    if (!person?.childIds?.length) return 1;

    const childDepths = person.childIds.map((cid) => getDepth(cid, visited));
    return 1 + Math.max(...childDepths);
  }

  const generations = roots.length > 0 ? Math.max(...roots.map((r) => getDepth(r.id))) : 0;

  // Find oldest/youngest by birth date
  const withBirthDates = people.filter((p) => p.birth?.date);
  const sorted = [...withBirthDates].sort((a, b) => {
    const dateA = new Date(a.birth!.date);
    const dateB = new Date(b.birth!.date);
    return dateA.getTime() - dateB.getTime();
  });

  return {
    totalPeople: people.length,
    totalRelationships: tree.relationships.length,
    generations,
    oldestPerson: sorted.at(0) ?? null,
    youngestPerson: sorted.at(-1) ?? null,
  };
}
